<script setup lang="ts">
import {qualityText as qt} from '../i18n'

import {defineAsyncComponent,onMounted,reactive,ref,watch} from 'vue'
import type {QualityClient} from '../client'
import {useQualityDetail} from '../useQualityDetail'
import {actions,orderStates,rectStates,time,type CheckRecord} from '../types'
const Media=defineAsyncComponent(()=>import('./QualityMedia.vue')),ActionForm=defineAsyncComponent(()=>import('./QualityActionForm.vue')),RepairForm=defineAsyncComponent(()=>import('./QualityRepairForm.vue'))
const props=defineProps<{api:QualityClient;id:string}>(),emit=defineEmits<{changed:[]}>(),vm=reactive(useQualityDetail(props.api)),repair=ref<{show:(record:CheckRecord)=>Promise<void>}>()
const reload=async()=>{await vm.load(props.id);emit('changed')}
watch(()=>props.id,()=>void vm.load(props.id));onMounted(()=>void vm.load(props.id))
</script>
<template><div class="quality-detail"><a-space style="margin-bottom:16px"><a-button :loading="vm.loading" @click="reload">{{qt('refresh')}}</a-button><a-tag v-if="vm.data" color="blue">{{orderStates[vm.data.workOrder.workOrderStatus]}}</a-tag></a-space><a-alert v-if="vm.error" type="error" :message="vm.error" show-icon /><a-alert v-if="vm.success" type="success" :message="vm.success" show-icon /><a-spin :spinning="vm.loading"><template v-if="vm.data">
 <a-descriptions :column="2" bordered size="small"><a-descriptions-item :label="qt('taskName')">{{vm.data.workOrder.taskName}}</a-descriptions-item><a-descriptions-item :label="qt('businessProject')">{{vm.data.workOrder.projectName}}</a-descriptions-item><a-descriptions-item :label="qt('orderNumber')">{{vm.data.workOrder.taskCode}}</a-descriptions-item><a-descriptions-item :label="qt('taskTemplate')">{{vm.data.workOrder.templateName}}</a-descriptions-item><a-descriptions-item :label="qt('generationTime')">{{time(vm.data.workOrder.scheduledTime)}}</a-descriptions-item><a-descriptions-item :label="qt('submissionTimeLimit')">{{time(vm.data.workOrder.reportDeadline)}}</a-descriptions-item><a-descriptions-item :label="qt('totalScore')">{{vm.data.workOrder.totalScore??'—'}}</a-descriptions-item><a-descriptions-item :label="qt('rating')">{{vm.data.workOrder.evaluationName||'—'}}</a-descriptions-item></a-descriptions>
 <a-space wrap style="margin:20px 0"><a-button v-if="vm.owned.length&&vm.can('inspect')" type="primary" @click="vm.start('inspect')">{{qt('startInspectionRestoreDraft')}}</a-button><a-button v-if="vm.owned.length&&vm.can('reassign')" @click="vm.start('reassign')">{{qt('reassignInspection2')}}</a-button><a-button v-if="vm.data.workOrder.workOrderStatus===1&&vm.can('dispatch')" @click="vm.start('dispatch')">{{qt('administrativeAssignment')}}</a-button></a-space>
 <a-tabs><a-tab-pane key="records" :tab="qt('checkDetails')"><a-card v-for="r in vm.data.records" :key="r.id" :title="r.checkContentName" size="small" style="margin-bottom:12px"><template #extra><a-tag :color="r.recordStatus===2?(r.isQualified?'green':'red'):'orange'">{{r.recordStatus===2?(r.isQualified?qt('qualified'):qt('unqualified')):r.recordStatus===3?qt('overdue'):qt('pendingInspection')}}</a-tag></template><p>{{r.subjectParentName}} / {{r.subjectName}} {{qt('inspector')}}{{r.executorName}}</p><p style="white-space:pre-wrap">{{r.checkRequirement}}</p><p v-if="r.deductionStandard">{{qt('deductionRule2')}}{{r.deductionStandard}}</p><p v-if="r.recordStatus===2">{{qt('score')}} {{r.score}} / {{r.originalScore}} · {{r.checkResult||'—'}}</p><p>{{qt('photoRequirements2')}}{{r.photoRequirement}}</p><Media :api="api" :ids="r.photoIds||[]" readonly /><div v-if="r.rectificationPhotoIds?.length"><p>{{qt('rectificationPhotos')}}</p><Media :api="api" :ids="r.rectificationPhotoIds" readonly /></div><a-button v-if="r.isQualified===0&&vm.can('transferRepair')" type="link" @click="repair?.show(r)">{{r.repairOrderId?qt('viewLinkedRepair'):qt('createRepair')}}</a-button></a-card></a-tab-pane>
 <a-tab-pane key="rectifications" :tab="qt('rectificationAndReview')+vm.data.rectifications.length+'）'"><a-empty v-if="!vm.data.rectifications.length" :description="qt('noRectificationTasks')" /><a-card v-for="rect in vm.data.rectifications" :key="rect.id" :title="rectStates[rect.rectificationStatus]" size="small" style="margin-bottom:12px"><p>{{qt('reviewer')}}{{rect.reviewerName}}</p><p>{{qt('issue2')}}{{rect.recordIds.map(id=>vm.record(id)?.checkContentName).join('、')}}</p><p v-if="rect.rectificationDesc">{{qt('rectificationDescription2')}}{{rect.rectificationDesc}}</p><a-alert v-if="rect.rejectReason" :message="qt('rejectionReason2')+rect.rejectReason" type="warning" show-icon /><a-space wrap><template v-if="vm.editableRects.some(r=>r.id===rect.id)&&vm.can('rectify')"><a-button type="primary" @click="vm.start('submit',rect.id)">{{qt('submitRectification')}}</a-button><a-button @click="vm.start('rectReassign',rect.id)">{{qt('reassignRectification2')}}</a-button></template><template v-if="vm.reviewable.some(r=>r.id===rect.id)&&vm.can('review')"><a-button type="primary" @click="vm.start('pass',rect.id)">{{qt('reviewPassed')}}</a-button><a-button danger @click="vm.start('reject',rect.id)">{{qt('reject')}}</a-button></template></a-space></a-card></a-tab-pane>
 <a-tab-pane key="history" :tab="qt('activityLog')"><a-timeline><a-timeline-item v-for="log in vm.data.history" :key="log.id"><strong>{{actions[log.action]||log.action}}</strong> · {{log.operatorName}}<p>{{time(log.createTime)}}</p><p v-if="log.details.description">{{log.details.description}}</p></a-timeline-item></a-timeline></a-tab-pane></a-tabs>
 </template><a-empty v-else-if="!vm.loading&&!vm.error" :description="qt('orderNotFound')" /></a-spin><ActionForm :api="api" :vm="vm" /><RepairForm ref="repair" :api="api" @changed="reload" /></div></template>
